const cache = new Map<Lang, ReturnType<typeof shape>>()

export function build(lang: Lang) {
  const found = cache.get(lang)
  if (found) return found
  index = languageCodes.indexOf(lang)
  const value = shape()
  cache.set(lang, value)
  return value
}

export const es = build('es')
export type Messages = typeof es

export const messages = Object.fromEntries(languageCodes.map((code) => [code, build(code)])) as Record<Lang, Messages>
